#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX_SIZE = 110;
int N;
vector<string> grid1, grid2;
vector<vector<int>> dist_matrix;

struct Edge {
    int src, dst, cap, cost;
    Edge(int s, int d, int c, int co) : src(s), dst(d), cap(c), cost(co) {}
};

struct MCMF {
    int node_count;
    vector<int> dist, prev_flow, prev_edge;
    vector<Edge> edge_list;
    int total_flow, total_cost;

    void init(int n) {
        node_count = n;
        dist.assign(n, INT_MAX);
        prev_flow.assign(n, 0);
        prev_edge.assign(n, -1);
    }

    void add_connection(int u, int v, int capacity, int cost_val) {
        edge_list.emplace_back(u, v, capacity, cost_val);
        edge_list.emplace_back(v, u, 0, -cost_val);
    }

    void relax_edges(int source, int sink) {
        init(node_count);
        prev_flow[source] = INT_MAX;
        dist[source] = 0;
        bool changed = true;
        for (int iter = 0; iter < node_count && changed; ++iter) {
            changed = false;
            for (size_t i = 0; i < edge_list.size(); ++i) {
                auto& e = edge_list[i];
                if (e.cap > 0 && dist[e.dst] > dist[e.src] + e.cost) {
                    dist[e.dst] = dist[e.src] + e.cost;
                    prev_flow[e.dst] = min(prev_flow[e.src], e.cap);
                    prev_edge[e.dst] = i;
                    changed = true;
                }
            }
        }
    }

    void compute(int source, int sink) {
        if (source == sink) {
            total_flow = INT_MAX;
            total_cost = 0;
            return;
        }
        total_flow = 0;
        total_cost = 0;
        while (true) {
            relax_edges(source, sink);
            if (prev_flow[sink] == 0) break;
            for (int cur = sink; cur != source; cur = edge_list[prev_edge[cur]].src) {
                int rev_idx = prev_edge[cur] ^ 1;
                edge_list[prev_edge[cur]].cap -= prev_flow[sink];
                edge_list[rev_idx].cap += prev_flow[sink];
                total_cost += edge_list[prev_edge[cur]].cost * prev_flow[sink];
            }
            total_flow += prev_flow[sink];
        }
    }
};

#define NODE_IN(x) (2 * (x))
#define NODE_OUT(x) (2 * (x) + 1)

MCMF solver;
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

void bfs(int sx, int sy, vector<vector<int>>& d) {
    d.assign(N, vector<int>(N, -1));
    d[sx][sy] = 0;
    queue<int> q;
    q.push(sx * N + sy);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int x = cur / N, y = cur % N;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N || d[nx][ny] != -1 || grid1[nx][ny] == 'Y') continue;
            if (isdigit(grid2[nx][ny]) && grid2[nx][ny] != '0' && (d[x][y] + 1 <= dist_matrix[nx][ny] || dist_matrix[nx][ny] == -1)) {
                d[nx][ny] = d[x][y] + 1;
                if (d[nx][ny] != dist_matrix[nx][ny]) q.push(nx * N + ny);
            } else if (dist_matrix[nx][ny] == -1 || dist_matrix[nx][ny] > d[x][y] + 1) {
                d[nx][ny] = d[x][y] + 1;
                q.push(nx * N + ny);
            }
        }
    }
}

void preprocess(vector<string>& m, vector<vector<vector<int>>>& all_dists) {
    all_dists.resize(N * N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(m[i][j]) && m[i][j] != '0')
                bfs(i, j, all_dists[i * N + j]);
}

void add_link(int i, int j, int x, int y) {
    int u = i * N + j;
    int v = x * N + y + N * N;
    solver.add_connection(NODE_OUT(u), NODE_IN(v), 1000000, 0);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.txt", "rt", stdin);
#endif
    int n, limit;
    cin >> n >> limit;
    N = n;
    vector<string> A(n), B(n);
    int start_x = -1, start_y = -1;
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
        for (int j = 0; j < n; ++j)
            if (A[i][j] == 'Z') {
                start_x = i;
                start_y = j;
            }
    }
    grid1 = A;
    for (int i = 0; i < n; ++i) cin >> B[i];
    grid2 = B;
    vector<vector<int>> temp_dist;
    vector<vector<vector<int>>> all_dists;
    dist_matrix.assign(N, vector<int>(N, 1000000000));
    bfs(start_x, start_y, temp_dist);
    dist_matrix = temp_dist;
    preprocess(A, all_dists);
    solver.init(4 * N * N + 2);
    int source = 4 * N * N, sink = source + 1;
    for (int i = 0; i < N * N; ++i) {
        solver.add_connection(source, NODE_IN(i), 1000000, 0);
        solver.add_connection(NODE_OUT(N * N + i), sink, 1000000, 0);
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (isdigit(A[i][j])) {
                int idx = i * N + j;
                solver.add_connection(NODE_IN(idx), NODE_OUT(idx), 0, A[i][j] - '0');
            }
            if (isdigit(B[i][j])) {
                int idx = i * N + j + N * N;
                solver.add_connection(NODE_IN(idx), NODE_OUT(idx), 0, B[i][j] - '0');
            }
        }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(B[i][j]) && B[i][j] != '0')
                for (int k = 0; k < (int)all_dists.size(); ++k)
                    if (!all_dists[k].empty()) {
                        int x = k / N, y = k % N;
                        if (all_dists[k][i][j] == -1 || all_dists[k][i][j] > limit) continue;
                        add_link(x, y, i, j);
                    }
    solver.compute(source, sink);
    cout << solver.total_flow << endl;
    return 0;
}
